using System;

public class AssertPart
{
    private readonly RunResult _measureResult;

    public AssertPart(RunResult measureResult)
    {
        _measureResult = measureResult;
    }

    public void NotExceedTotalTime(TimeSpan maxAllowedTime)
    {
        if (_measureResult.ElapsedTime > maxAllowedTime)
        {
            throw new TimeExceededException($"Measured time {_measureResult.ElapsedTime} exceeds the allowed time {maxAllowedTime}");
        }
    }
}

public class RunResult
{
    public long ElapsedTime { get; }

    public RunResult(long elapsedTicks)
    {
        ElapsedTime = new TimeSpan(elapsedTicks).Duration().Ticks;
    }
}

public class TimeExceededException : Exception
{
    public TimeExceededException(string message) : base(message) { }
}
```

