   ScoringSystem getScoringSystem();
}

// Interface for dispute
interface DisputeHandler {
   boolean isValidDispute(Dispute dispute);
   void resolveDispute(Dispute dispute);
}

// Concurrency design considerations
// For managing tournament and sending updates to multiple observers real-time, the Observer design pattern can be used.
// The TournamentManager is an Observable which gets updated if there is a change in the tournament score. Observers (like user interface) will get notified on score change.

class TournamentManager extends Observable {
   private ScoringSystem scoringSystem;
   private DisputeHandler disputeHandler;
   ...

   void notifyScoreChange() {
      setChanged();
      notifyObservers();
   }

   void resolveDispute(Dispute dispute) {
      disputeHandler.resolveDispute(dispute);
      notifyScoreChange();
   }
