pub struct SealedSectorMetadata {
    // Define sealed sector metadata fields
}

impl StagedState {
    pub fn add_sector(&mut self, sector_id: SectorId, metadata: StagedSectorMetadata) {
        self.sectors.insert(sector_id, metadata);
    }

    pub fn remove_sector(&mut self, sector_id: &SectorId) {
        self.sectors.remove(sector_id);
    }

    pub fn get_sector_metadata(&self, sector_id: &SectorId) -> Option<&StagedSectorMetadata> {
        self.sectors.get(sector_id)
    }
}

impl SealedState {
