class SessionValidator
{
    private $predefinedSessionId = '1234567890';
    private $predefinedUserId = '099999';

    public function validate($sessionId, $userId)
    {
        if (!preg_match('/^\d{10}$/', $sessionId)) {
            throw new InvalidSessionException('Invalid session ID format');
        }

        if (!preg_match('/^\d{6}$/', $userId)) {
            throw new InvalidUserException('Invalid user ID format');
        }

        if ($sessionId !== $this->predefinedSessionId || $userId !== $this->predefinedUserId) {
