// Define the TV show cell view model
struct TVShowCellViewModel {
    // Properties and methods for the TV show cell view model
}

// Define the SectionModelType protocol
protocol SectionModelType {
    associatedtype Item
    init(original: Self, items: [Item])
}

// Implement the TVShowList struct
struct TVShowList<Item>: SectionModelType {
    private var sections: [(title: String, items: [Item])] = []

    // Add a new section with a given title and an array of TV show cell view models
    mutating func addSection(title: String, items: [Item]) {
        sections.append((title: title, items: items))
    }

    // Remove a section by its index
    mutating func removeSection(at index: Int) {
        guard index >= 0, index < sections.count else { return }
        sections.remove(at: index)
    }

    // Access the total count of sections
    var numberOfSections: Int {
        return sections.count
    }

    // Access the count of items in a specific section
    func numberOfItems(inSection section: Int) -> Int {
        guard section >= 0, section < sections.count else { return 0 }
        return sections[section].items.count
    }

    // Access a specific TV show cell view model given its section index and item index within that section
    func item(at indexPath: (section: Int, item: Int)) -> Item? {
        guard indexPath.section >= 0, indexPath.section < sections.count else { return nil }
        guard indexPath.item >= 0, indexPath.item < sections[indexPath.section].items.count else { return nil }
        return sections[indexPath.section].items[indexPath.item]
    }

    // Implement the required initializer from the SectionModelType protocol
    init(original: TVShowList<Item>, items: [Item]) {
        self = original
        self.sections = [(title: "", items: items)]
    }
}
```

