from typing import List

def product_sans_n(nums: List[int]) -> List[int]:
    if nums.count(0) >= 2:
        return [0] * len(nums)
    elif nums.count(0) == 1:
        temp = [0] * len(nums)
        temp[nums.index(0)] = product(nums)
        return temp
    res = product(nums)
    return [res // i if i != 0 else 0 for i in nums]

def product(arr: List[int]) -> int:
    total = 1
    for num in arr:
        if num != 0:
            total *= num
    return total
