def process_data(candidates: dict, df_spec2model: dict) -> (set, dict):
    all_molecules = set()
    molecule_counts = {}

    # Extract unique molecules from candidates
    for model, prediction_list in candidates.items():
        for item in prediction_list:
            if isinstance(item, tuple):
                cid_can, _ = item
                all_molecules.add(cid_can)
                molecule_counts[cid_can] = molecule_counts.get(cid_can, 0) + 1

    # Extract unique molecules from df_spec2model
    for model, spec_list in df_spec2model.items():
        for spec in spec_list:
            _, cid, _, _, _ = spec
            all_molecules.add(cid)
            molecule_counts[cid] = molecule_counts.get(cid, 0) + 1

    return all_molecules, molecule_counts
