def modify_setting(name, value, settings):
    def decorator(fn):
        def wrapper(*args, **kwargs):
            original = getattr(settings, name)
            setattr(settings, name, value)
            try:
                return fn(*args, **kwargs)
            finally:
                setattr(settings, name, original)
        return wrapper
    return decorator

# Example usage
