func validateString(_ input: String) -> String {
    if input.range(of: "^[A-Z]+$", options: .regularExpression) != nil {
        return "Uppercase English letters only"
    } else if input.range(of: "^[a-z]+$", options: .regularExpression) != nil {
        return "Lowercase English letters only"
    } else if input.range(of: "^[A-Za-z0-9]+$", options: .regularExpression) != nil {
        return "English letters and numbers only"
    } else if input.range(of: "^\\w+$", options: .regularExpression) != nil {
        return "English letters, numbers, and underscores only"
    } else if input.range(of: "^[\\u4E00-\\u9FA5A-Za-z0-9_]+$", options: .regularExpression) != nil {
        return "Chinese, English letters, numbers, and underscores"
    } else if input.range(of: "^[\\u4E00-\\u9FA5A-Za-z0-9]+$", options: .regularExpression) != nil {
        return "Chinese, English letters, and numbers only"
    } else {
        return "Unknown Type"
    }
