    echo "'{$substring}', ";
}

echo "\n";

// Check if original string ends with given character
if(substr($string, -1) === $character){
    echo "The original string '{$string}' ends with character '{$character}'.";
} else {
    echo "The original string '{$string}' does not end with character '{$character}'.";
}

?>
