            {
                if (balances.Values.Contains(ch))
                {
                    stack.Add(stack.Count);
                } 
                else if (stack.Count > 0 && balances[ch] == groups[stack.Last()].Last())
                {
                    int index = stack.Last();
                    stack.RemoveAt(stack.Count - 1);
                    groups[index].Add(ch);
                    if (stack.Count > 0)
                    {
                        groups[stack.Last()].AddRange(groups[index]);
                        groups.Remove(index);
                    }
                }
                else
                {
                    return new List<string>();
                }
            }
        }
        return groups.OrderBy(g => g.Key).Select(g => string.Join("", g.Value)).ToList();
    }
