```python
class PhaseManager:
    def __init__(self):
        self._Tb = 0  # Boiling point temperature
        self._Tm = 0  # Melting point temperature
        self._phase_ref = 'g'  # Reference phase

    @property
    def phase(self):
        return self._phase_ref

    @phase.setter
    def phase(self, phase):
        if phase == 's' and self._Tm >= self._Tb:
            raise ValueError("Melting point temperature should be lower than boiling point temperature")
        elif phase == 'l' and (self._Tm >= self._Tb or self._Tm <= 0):
            raise ValueError("Melting point temperature should be lower than boiling point temperature and greater than 0")
        elif phase == 'g' and self._Tb <= 0:
            raise ValueError("Boiling point temperature should be greater than 0 for gas phase")
        else:
            self._phase_ref = phase

    @property
    def Tb(self):
        return self._Tb

    @Tb.setter
    def Tb(self, temperature):
        if self._phase_ref == 'g' and temperature <= 0:
            raise ValueError("Boiling point temperature should be greater than 0 for gas phase")
        elif self._phase_ref == 'l' and (temperature <= self._Tm or temperature <= 0):
            raise ValueError("Boiling point temperature should be greater than melting point temperature and greater than 0")
        else:
            self._Tb = temperature

    @property
    def Tm(self):
        return self._Tm

    @Tm.setter
    def Tm(self, temperature):
        if self._phase_ref == 'g' and temperature <= 0:
            raise ValueError("Melting point temperature should be greater than 0 for gas phase")
        elif self._phase_ref == 's' and temperature >= self._Tb:
            raise ValueError("Melting point temperature should be lower than boiling point temperature")
        else:
            self._Tm = temperature
```

