Here is a simple implementation of a hash table using Python. It assumes that you will be using string keys to insert, retrieve and delete from the hash table. The hash function just uses the built-in `hash` function in Python, which will suffice for this example but could be replaced with a more complex hash function if needed.

```python
class HashTable:
    def __init__(self):
        self.size = 10000
        self.table = [None] * self.size

    def _hash(self, key):
        return hash(key) % self.size

    def insert(self, key, value):
        index = self._hash(key)
        if self.table[index] is not None:
            for kvp in self.table[index]:
                if kvp[0] == key:
                    kvp[1] = value
                    break
            else:
                self.table[index].append([key, value])
        else:
            self.table[index] = [[key, value]]

    def retrieve(self, key):
        index = self._hash(key)
        if self.table[index] is not None:
            for kvp in self.table[index]:
                if kvp[0] == key:
                    return kvp[1]
        return None

    def delete(self, key):
        index = self._hash(key)
        if self.table[index] is not None:
            for i in range(len(self.table[index])):
                if self.table[index][i][0] == key:
                    self.table[index].pop(i)
                    break
```

