import java.io.Serializable;
import java.io.ObjectInputStream;
import java.io.ObjectOutputStream;
import java.io.IOException;
import java.math.BigDecimal;

public class CustomObject implements Serializable {
    private BigDecimal bigDecimalField;

    public CustomObject(BigDecimal bigDecimalField) {
        this.bigDecimalField = bigDecimalField;
    }

    public void serializeObject(String filePath) {
        try (ObjectOutputStream oos = new ObjectOutputStream(new FileOutputStream(filePath))) {
            oos.writeObject(this);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    public static CustomObject deserializeObject(String filePath) {
        CustomObject customObject = null;
        try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(filePath))) {
            customObject = (CustomObject) ois.readObject();
        } catch (IOException | ClassNotFoundException e) {
            e.printStackTrace();
        }
        return customObject;
    }

    private void writeObject(ObjectOutputStream out) throws IOException {
        out.defaultWriteObject();
        out.writeUTF(bigDecimalField.toString());
    }

    private void readObject(ObjectInputStream in) throws IOException, ClassNotFoundException {
        in.defaultReadObject();
        bigDecimalField = new BigDecimal(in.readUTF());
    }
}
```

