```javascript
// Complete ColorManager class with computed decorator
class ColorManager {
  constructor(colors) {
    this.colors = colors;
  }

  // Define computed decorator
  computed(target, name, descriptor) {
    const getter = descriptor.get;
    descriptor.get = function () {
      if (!this._computedCache) {
        this._computedCache = {};
      }
      const key = `__computed__${name}`;
      if (!this._computedCache[key]) {
        this._computedCache[key] = getter.call(this);
      }
      return this._computedCache[key];
    };
    return descriptor;
  }

  @computed
  get ColorText() {
    return `Color is: ${this.colors.primary} + ${this.colors.secondary}`;
  }
}

