import ast

def count_third_party_imports(file_path):
    with open(file_path, 'r') as file:
        content = file.read()

    tree = ast.parse(content)
    third_party_imports = 0

    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            for alias in node.names:
                if not alias.name.startswith('.') and not alias.name.startswith('from '):
                    third_party_imports += 1
        elif isinstance(node, ast.ImportFrom) and not node.module.startswith('.'):
            third_party_imports += 1

    return third_party_imports
